  "Per le condizioni giuridiche e commerciali complete consulta i documenti pubblicati nel footer. Per un problema relativo a uno specifico ordine, verifica prima le informazioni del Venditore e dell'ordine.": "Para conocer las condiciones legales y comerciales completas, consulte los documentos publicados en el pie de página. Para un problema relacionado con un pedido específico, primero verifique el vendedor y la información del pedido.",
  "Guida locale": "guía local",
  "La città": "la ciudad",
  "Identità locale": "Identidad local",
  "Castrovillari vive tutto l'anno attraverso teatro, musica, folklore, libri, arte e iniziative di comunità. Il calendario cambia di anno in anno: per date confermate e programmi completi fai riferimento agli organizzatori.": "Castrovillari vive todo el año a través del teatro, la música, el folklore, los libros, el arte y las iniciativas comunitarias. El calendario cambia de año en año: para fechas confirmadas y programas completos consulte a los organizadores.",
  "Da non perdere": "No te lo puedes perder",
  "Gusto e territorio": "Sabor y territorio",
  "Scopri le tradizioni gastronomiche di Castrovillari e del Pollino, compresa la Cipolla Bianca di Castrovillari, riconosciuta De.Co. Per produttori, stagionalità e iniziative enogastronomiche consulta le fonti locali e gli eventi in programma.": "Descubra las tradiciones gastronómicas de Castrovillari y Pollino, incluida la Cebolla Blanca de Castrovillari, reconocida por De.Co. Para productores, estacionalidad e iniciativas enogastronómicas, consulte fuentes locales y eventos programados.",
