  "Il tuo riepilogo personale: ordini, preferiti, offerte ed eventi.": "Tu resumen personal: pedidos, favoritos, ofertas y eventos.",
  "Il riepilogo della tua attività su Radici Calabria: ordini, preferiti e ultimi acquisti, sempre a portata di mano.": "El resumen de tu actividad en Radici Calabria: pedidos, favoritos y últimas compras, siempre a mano.",
  "Storico dei tuoi ordini con lo stato di spedizione e consegna.": "Historial de tus pedidos con estado de envío y entrega.",
  "Lo storico completo dei tuoi acquisti, salvato sul tuo account: ritorna quando vuoi e ritrova ogni ordine con il suo stato.": "El historial completo de tus compras, guardado en tu cuenta: regresa cuando quieras y encuentra cada pedido con su estado.",
  "Negozi e prodotti salvati per non perderli di vista.": "Tiendas y productos guardados para que no los pierdas de vista.",
