  "Hai un account? I tuoi ordini restano qui per sempre.": "¿Tienes una cuenta? Tus órdenes se quedan aquí para siempre.",
  "I tuoi ordini restano al sicuro: servono entrambi i dati per trovarli": "Tus pedidos permanecen seguros: necesitas ambos datos para encontrarlos",
  "Puoi recuperare i tuoi ordini in qualsiasi momento inserendo email e telefono usati al checkout.": "Puede recuperar sus pedidos en cualquier momento ingresando el correo electrónico y el número de teléfono utilizados al finalizar la compra.",
  "Hai acquistato senza account? Inserisci l'email e il telefono usati al momento dell'ordine.": "¿Compraste sin una cuenta? Introduzca el correo electrónico y el número de teléfono utilizados al realizar el pedido.",
  "Inserisci sia l'email sia il telefono usati per l'ordine.": "Introduce tanto el correo electrónico como el número de teléfono utilizado para el pedido.",
  "Verifica che email e telefono coincidano con quelli usati al checkout.": "Comprueba que tu correo electrónico y número de teléfono coincidan con los utilizados al realizar el pago.",
  "Puoi ritrovare questo ordine in qualsiasi momento dalla tua area personale, anche dopo aver chiuso il browser.": "Podrás encontrar este pedido en cualquier momento desde tu área personal, incluso después de cerrar el navegador.",
  "Se ti registri e accedi come cliente, i tuoi prossimi acquisti compariranno automaticamente nella tua area personale.": "Si te registras e inicias sesión como cliente, tus próximas compras aparecerán automáticamente en tu área personal.",
