  "Non ci sono ancora notizie disponibili.": "Aún no hay noticias disponibles.",
  "L'aggregatore raccoglie le notizie di Castrovillari periodicamente. Torna presto a trovarci.": "El agregador recoge periódicamente noticias de Castrovillari. Vuelve y visítanos pronto.",
  "Le notizie di Castrovillari raccolte automaticamente da fonti istituzionali e pubbliche: Comune, Provincia, Regione, Parco del Pollino e Protezione Civile.": "Noticias de Castrovillari recopiladas automáticamente de fuentes institucionales y públicas: Municipio, Provincia, Región, Parque Pollino y Protección Civil.",
  "Google News · Castrovillari": "Google Noticias · Castrovillari",
  "Google News · Castrovillari Comune": "Google Noticias · Municipio de Castrovillari",
  "Radici Calabria collega produttori, trasformatori, distributori e consumatori: le filiere dei territori arrivano in città.": "Radici Calabria conecta a productores, transformadores, distribuidores y consumidores: las cadenas de suministro locales llegan a la ciudad.",
  "Una piattaforma che valorizza le produzioni, le imprese e le identità territoriali, collegando produttori, trasformatori, distributori e consumatori.": "Una plataforma que potencia producciones, negocios e identidades territoriales, conectando a productores, procesadores, distribuidores y consumidores.",
  "Le offerte e le promozioni dei produttori e dei negozi del territorio: prodotti in sconto selezionati tra le filiere locali.": "Ofertas y promociones de productores y comercios locales: productos con descuento seleccionados de cadenas de suministro locales.",
  "Le migliori offerte dei negozi di Castrovillari": "Las mejores ofertas de las tiendas en Castrovillari",
  "Le eccellenze di Castrovillari e del Pollino: cipolle bianche, mieli e prodotti tipici selezionati dalle filiere del territorio.": "Las excelencias de Castrovillari y Pollino: cebollas blancas, miel y productos típicos seleccionados de las cadenas locales.",
  "Scopri monumenti, musei, cultura, eventi, sapori e borghi nei dintorni di Castrovillari e del Parco Nazionale del Pollino.": "Descubra monumentos, museos, cultura, eventos, sabores y pueblos en los alrededores de Castrovillari y el Parque Nacional Pollino.",
  "Non ci sono ancora prodotti in promozione. Esplora i negozi e le produzioni del territorio.": "Aún no hay productos en promoción. Explore las tiendas y productos locales.",
  "Non ci sono ancora prodotti nella vetrina territoriale. Esplora i negozi e le produzioni del territorio.": "Aún no hay productos en el escaparate local. Explore las tiendas y productos locales.",
  "Presto potrai trovare promozioni esclusive dai negozi della tua città.": "Próximamente podrás encontrar promociones exclusivas de las tiendas de tu ciudad.",
  "I prodotti dei negozi locali saranno visibili qui appena disponibili.": "Los productos de las tiendas locales serán visibles aquí tan pronto como estén disponibles.",
  "Aggiungi prodotti dalle filiere del territorio prima di procedere al checkout.": "Agregue productos de cadenas de suministro locales antes de realizar el pago.",
  "Completa il tuo ordine su Radici Calabria: ritiro o spedizione dai produttori e dai negozi del territorio.": "Complete su pedido en Radici Calabria: recogida o envío a productores y comercios locales.",
  "Acquista senza account oppure accedi per usare i dati del tuo profilo.": "Compra sin una cuenta o inicia sesión para utilizar tus datos de perfil.",
  "Stai acquistando come ospite: non è richiesta la registrazione, compila i tuoi dati per l'ordine.": "Estás comprando como invitado: no es necesario registrarse, completa los datos de tu pedido.",
  "Stai acquistando come ospite: non è richiesta la registrazione, indica solo chi ritira.": "Estás comprando como invitado: no es necesario registrarse, sólo indicar quién recoge.",
  "Stai acquistando come ospite: compila i tuoi dati qui sotto. Non è richiesta la registrazione.": "Estás comprando como invitado: completa tus datos a continuación. No es necesario registrarse.",
  "Usiamo l'indirizzo del tuo profilo. Puoi cambiarlo solo per questo ordine senza modificare il profilo.": "Usamos su dirección de perfil. Puedes cambiarlo solo para este pedido sin modificar el perfil.",
  "Puoi cambiarlo solo per questo ordine senza modificare il profilo.": "Puedes cambiarlo solo para este pedido sin modificar el perfil.",
  "Account Google autenticato. Completa solo i dati dell'attività per concludere la registrazione.": "Cuenta de Google autenticada. Complete solo los detalles del negocio para completar el registro.",
  "Registrazione completata e accesso effettuato. Il tuo account è ora in attesa dell'approvazione dell'amministratore prima di poter utilizzare le aree personali della piattaforma.": "Registro completado e iniciado sesión. Su cuenta ahora está esperando la aprobación del administrador antes de poder utilizar las áreas personales de la plataforma.",
  "Ti abbiamo inviato una email di conferma della registrazione. Non devi fare altro: riceverai una nuova comunicazione quando l'amministratore avrà deciso.": "Le hemos enviado un correo electrónico confirmando su registro. No tienes que hacer nada más: recibirás una nueva comunicación cuando el administrador lo haya decidido.",
  "Ti abbiamo inviato un'email per confermare la registrazione. Clicca sul link contenuto nel messaggio per attivare il tuo account.": "Le hemos enviado un correo electrónico para confirmar su registro. Haga clic en el enlace del mensaje para activar su cuenta.",
