  "Stato richiesto: aperte, turno o tutte.": "Estado solicitado: abierto, turno o todo.",
  "Cerca farmacie aperte, di turno o tutte.": "Busque farmacias que estén abiertas, de turno o todas.",
  "Ciao! Sono l'Assistente di LocalHub": "¡HOLA! Soy el asistente de LocalHub",
  "Cerca offerte, promozioni e sconti attivi.": "Busque ofertas, promociones y descuentos activos.",
  "Cerca eventi, manifestazioni e appuntamenti.": "Búsqueda de eventos, manifestaciones y citas.",
  "Cerca prodotti acquistabili nel catalogo locale.": "Busque productos adquiribles en el catálogo local.",
  "Restituisce il meteo aggiornato di Castrovillari.": "Devuelve el tiempo actualizado de Castrovillari.",
  "Cerca negozi, attività, professionisti e servizi locali.": "Búsqueda de comercios, negocios, profesionales y servicios locales.",
  "Elenca le categorie del catalogo con il numero di negozi.": "Enumera las categorías del catálogo con el número de tiendas.",
  "Cerca articoli e contenuti editoriali pubblicati su Radici Calabria.": "Busque artículos y contenido editorial publicados en Radici Calabria.",
  "Chiedi qualcosa… es. farmacia aperta adesso, pizzeria in centro": "Preguntar algo... p.e. farmacia abierta ahora, pizzería en el centro",
  "Cerca le ultime notizie pubblicate su Radici Calabria, con fonte e link.": "Busque las últimas noticias publicadas sobre Radici Calabria, con fuente y enlace.",
  "Cerca prodotti nelle categorie regalo; strumento interno al fan-out.": "Busque productos en las categorías de regalos; instrumento interno al fan-out.",
  "Posso aiutarti a trovare negozi, servizi e attività locali. Dimmi cosa cerchi!": "Puedo ayudarte a encontrar tiendas, servicios y negocios locales. ¡Cuéntame qué estás buscando!",
  "Cerca trasversalmente negozi, prodotti, offerte, eventi, notizie, contenuti e categorie.": "Busque en tiendas, productos, ofertas, eventos, noticias, contenido y categorías.",
  "Sono il tuo assistente allo shopping su Radici Calabria. Posso aiutarti a trovare negozi, prodotti e servizi nella tua città.": "Soy tu asistente de compras en Radici Calabria. Puedo ayudarte a encontrar tiendas, productos y servicios en tu ciudad.",
  "La guida di Radici Calabria invita a scoprire le tradizioni gastronomiche di Castrovillari e del Pollino, compresa la Cipolla Bianca. La vetrina Eccellenze Calabresi mostra i prodotti effettivamente pubblicati dai negozi.": "La guía Radici Calabria le invita a descubrir las tradiciones gastronómicas de Castrovillari y Pollino, incluida la cebolla blanca. El escaparate de Eccellenze Calabresi muestra los productos realmente publicados por las tiendas.",
