  "· il link pubblico del prodotto resta invariato.": "· el enlace público del producto permanece sin cambios.",
  "Cerca per operazione, risorsa, email, negozio...": "Búsqueda por operación, recurso, correo electrónico, tienda...",
  "Cerca per titolo, descrizione, email, oggetto...": "Busca por título, descripción, correo electrónico, asunto...",
  "Es. articolo non disponibile, richiesta cliente…": "Por ej. artículo no disponible, petición del cliente…",
