  "11. Conclusione del contratto": "11. Celebración del contrato",
  "11. Rapporto tra Acquirente e Venditore": "11. Relación entre Comprador y Vendedor",
  "12. Conferma dell'ordine": "12. Confirmación del pedido",
  "12. Pagamenti e autorizzazione del pagamento": "12. Pagos y autorización de pago",
  "12. Responsabilità e limiti del ruolo di Radici Calabria": "12. Responsabilidades y límites del papel de Radici Calabria",
  "13. Conferma dell'ordine": "13. Confirmación del pedido",
  "13. Modifiche del regolamento": "13. Modificaciones del reglamento",
