  "14. Consegna, ritiro o prestazione del servizio": "14. Entrega, recogida o prestación del servicio",
  "14. Elaborazione tecnica del pagamento": "14. Procesamiento técnico de pagos",
  "14. Normativa applicabile e prevalenza dei contratti": "14. Legislación aplicable y prevalencia de los contratos",
  "15. Comunicazioni relative all'ordine": "15. Comunicaciones relativas al pedido",
  "15. Consegna, ritiro o prestazione del servizio": "15. Entrega, recogida o prestación del servicio",
