  "Patata della Sila IGP": "Patata de Sila IGP",
  "Finocchio di Isola Capo Rizzuto IGP": "Hinojo de Isola Capo Rizzuto IGP",
  "La Liquirizia di Calabria DOP nasce nei terreni alluvionali della piana di Sibari, dove la lavorazione della radice è tradizione antica.": "Licorice di Calabria DOP nace en los suelos aluviales de la llanura de Sibari, donde el procesamiento de la raíz es una antigua tradición.",
  "La pianta cresce spontanea nei terreni sciolti della piana e la lavorazione trasforma la radice in estratto, sciroppo e pasta. Le radici si estirpano in inverno, quando la pianta è in riposo e concentra gli zuccheri.": "La planta crece espontáneamente en el suelo suelto de la llanura y el procesamiento transforma la raíz en extracto, almíbar y pasta. Las raíces se arrancan en invierno, cuando la planta está inactiva y concentra los azúcares.",
  "Dai pastifici storici di Rossano escono caramelle, bastoncini e liquirizia pura, spesso venduta sfusa nelle botteghe del centro storico. L'estratto si lavora a caldo e poi riposa, così la pasta acquista la consistenza lucida e la frattura netta tipiche.": "De las históricas fábricas de pasta de Rossano proceden los dulces, las barritas y el regaliz puro, que a menudo se venden a granel en las tiendas del centro histórico. El extracto se trabaja en caliente y luego reposa, por lo que la pasta adquiere la típica consistencia brillante y fractura clara.",
  "Estirpazione delle radici e pulizia": "Eliminación y limpieza de raíces.",
  "Estrazione a caldo e concentrazione dell'estratto": "Extracción en caliente y concentración del extracto.",
  "Formatura in bastoncini, caramelle o pasta sfusa": "Dar forma de palitos, caramelos o pasta suelta.",
  "Le radici si raccolgono in autunno e inverno.": "Las raíces se recolectan en otoño e invierno.",
  "Radice essiccata": "raíz seca",
  "Estratto e sciroppo": "Extracto y almíbar",
  "Caramelle e bastoncini": "dulces y palos",
  "Liquirizia pura sfusa": "Regaliz puro a granel",
  "Polvere per bevande": "polvo para bebidas",
  "Liquirizia di Calabria DOP": "Regaliz de Calabria DOP",
  "Fichi di Cosenza DOP e Torrone di Bagnara IGP: la dolciaria calabrese unisce la frutta essiccata al sole alle mandorle del territorio.": "Higos de Cosenza DOP y Torrone di Bagnara IGP: la repostería calabresa combina frutos secos con almendras locales.",
  "Il Fico Dottato si essicca al sole su cannizzi e viene farcito con agrumi canditi e mandorle, poi legato a grappoli: è la base della schiocca e dei fichi imbottiti, dolci che si preparano in famiglia ancora oggi.": "El Fico Dottato se seca al sol sobre cannizzi y se rellena con cítricos confitados y almendras, luego se ata en manojos: es la base de la schiocca y de los higos rellenos, postres que aún hoy se preparan en la familia.",
  "A Bagnara Calabra il torrone nasce dalla lavorazione di mandorle, miele e albume, con una tradizione dolciaria che risale ai banchi dei confettieri. La mostarda chiude il cerchio, unendo la frutta al mosto cotto.": "En Bagnara Calabra el turrón procede de la elaboración de almendras, miel y clara de huevo, con una tradición repostera que se remonta a los puestos de pastelería. La mostaza cierra el círculo, combinando la fruta con el mosto cocido.",
  "Raccolta dei fichi maturi in agosto": "Cosecha de higos maduros en agosto.",
  "Essiccazione al sole su cannizzi, con volteggio quotidiano": "Secado al sol en cannizzi, con rotación diaria.",
  "Farcitura, legatura a grappoli e conservazione": "Relleno, atado de racimos y conservación.",
  "Fichi freschi in agosto; secchi e lavorati da settembre.": "higos frescos en agosto; secado y procesado a partir de septiembre.",
  "Fichi secchi e schiocca": "Higos secos y paletas",
  "Fichi imbottiti": "Higos rellenos",
  "Torrone": "turrón",
  "Mostarde e confetture": "Mostazas y mermeladas",
  "Mandorle e frutta secca": "Almendras y frutos secos",
  "Fichi di Cosenza DOP": "Higos de Cosenza DOP",
  "Torrone di Bagnara IGP": "Turrón de Bagnara IGP",
  "Pesca costiera tra Tirreno e Ionio, acquacoltura e tradizioni marinare: dalle marinerie di Scilla e Bagnara ai porti del Crotonese.": "Pesca costera entre los mares Tirreno y Jónico, acuicultura y tradiciones marítimas: desde los puertos deportivos de Scilla y Bagnara hasta los puertos de Crotone.",
  "Le marinerie dello Stretto lavorano pesce azzurro, alici e pesce spada con tecniche tramandate di padre in figlio; lungo lo Ionio l'acquacoltura alleva orate e branzini in mare aperto, in gabbie ancorate al largo.": "Los puertos deportivos del Estrecho procesan pescado azul, anchoa y pez espada con técnicas transmitidas de padres a hijos; A lo largo del mar Jónico, la acuicultura cría dorada y lubina en mar abierto, en jaulas ancladas en alta mar.",
  "La filiera corta dei porti rifornisce pescherie e ristoranti con il pescato del giorno. Alici e sardine si conservano sott'olio o sotto sale, mentre il pesce spada si lavora a trancio già sulla banchina, tra ghiaccio e casse.": "La corta cadena de suministro en los puertos abastece a pescaderías y restaurantes con la pesca del día. Las anchoas y las sardinas se conservan en aceite o sal, mientras que el pez espada se corta en lonchas en el muelle, entre hielo y cajas.",
  "Pesca costiera notturna o all'alba, con reti e palangari": "Pesca costera de noche o de madrugada, con redes y palangres",
  "Selezione e ghiaccio a bordo, poi asta del pesce al porto": "Selección y hielo a bordo, luego subasta de pescado en el puerto.",
  "Conservazione sott'olio, sotto sale o abbattimento per il fresco": "Conservación en aceite, sal o refrigeración para almacenamiento en fresco",
  "Pesce azzurro soprattutto in primavera ed estate; pesce spada da maggio a settembre.": "Pescado azul especialmente en primavera y verano; pez espada de mayo a septiembre.",
