  "Per informazioni sui negozi, sui prodotti o sul funzionamento della piattaforma scrivici: ti rispondiamo il prima possibile.": "Para información sobre las tiendas, productos o cómo funciona la plataforma, escríbenos: te responderemos lo antes posible.",
  "Per un problema relativo a un ordine specifico, contatta prima il Venditore attraverso i recapiti indicati nella scheda del negozio o dell'ordine. Per il supporto tecnico sulla piattaforma puoi scriverci": "Para un problema relacionado con un pedido específico, primero comuníquese con el Vendedor a través de los datos de contacto indicados en la tienda o en la tarjeta de pedido. Para soporte técnico en la plataforma puedes escribirnos",
