  "Riconoscimento e verifica dei prodotti": "Reconocimiento y verificación de los productos",
  "TerraQ è il servizio di Radici Calabria per riconoscere e verificare i prodotti. Questa pagina è pronta per ospitarlo.": "TerraQ es el servicio de Radici Calabria para reconocer y verificar los productos. Esta página está lista para alojarlo.",
  "Servizio in arrivo": "Servicio próximamente",
  "Nel frattempo il catalogo dei prodotti resta disponibile nella sezione Filiere, con categorie, schede prodotto, prezzi, disponibilità e acquisto.": "Mientras tanto, el catálogo de productos sigue disponible en la sección Cadenas de suministro, con categorías, fichas de producto, precios, disponibilidad y compra.",
  "La rinascita verde della Calabria": "El renacimiento verde de Calabria",
  "Quattro anni di crescita record, innovazione e conquista dei mercati globali.": "Cuatro años de crecimiento récord, innovación y conquista de mercados globales.",
  "C’è una Calabria che non si limita a custodire le proprie tradizioni millenarie, ma le trasforma in un motore economico moderno, competitivo e riconosciuto in tutto il mondo. Negli ultimi quattro anni, tra il 2022 e il 2026, il comparto agroalimentare calabrese è stato protagonista di una vera e propria svolta strutturale: un percorso fatto di numeri da primato, investimenti mirati e una visione istituzionale condivisa che ha saputo fare squadra con gli agricoltori, portando le eccellenze della regione sulle tavole internazionali.": "Hay una Calabria que no se limita a conservar sus tradiciones milenarias, sino que las transforma en un motor económico moderno, competitivo y reconocido mundialmente. En los últimos cuatro años, entre 2022 y 2026, el sector agroalimentario de Calabria ha sido protagonista de un verdadero punto de inflexión estructural: un camino caracterizado por cifras récord, inversiones específicas y una visión institucional compartida que ha sabido asociarse con los agricultores, llevando la excelencia de la región a las mesas internacionales.",
  "incidenza agricoltura sul PIL regionale": "Impacto de la agricultura en el PIB regional.",
  "valore aggiunto per unità di lavoro dal 2022": "valor añadido por unidad de trabajo a partir de 2022",
  "aziende agroindustriali con produzione in aumento": "Empresas agroindustriales con creciente producción.",
  "del valore dell'export regionale è food & beverage": "del valor de las exportaciones regionales son alimentos y bebidas",
  "indice export agroalimentare (pre-pandemia = 100)": "índice de exportaciones agroalimentarias (prepandemia = 100)",
  "della superficie agricola coltivata con metodo biologico": "de la superficie agrícola cultivada orgánicamente",
  "Un motore economico": "Un motor económico",
  "Che corre più della media nazionale": "Que corre más rápido que el promedio nacional.",
  "Incidenza dell'agricoltura sul PIL regionale": "Incidencia de la agricultura en el PIB regional",
  "Valore aggiunto per unità di lavoro (2022 → 2026)": "Valor agregado por unidad de trabajo (2022 → 2026)",
  "Aziende agroindustriali con produzione reale in aumento": "Empresas agroindustriales con producción real creciente",
  "Quasi il triplo rispetto alla media italiana.": "Casi el triple que la media italiana.",
  "Crescita cinque volte superiore alla media nazionale.": "Crecimiento cinco veces superior al promedio nacional.",
  "Oltre i tre quarti del comparto.": "Más de las tres cuartas partes del sector.",
  "La spinta produttiva si è tradotta in una straordinaria apertura verso l’estero: l’export complessivo della Calabria ha infranto il muro simbolico del miliardo di euro, trainato dal food & beverage che rappresenta quasi il 40% delle vendite oltreconfine.": "El impulso productivo se ha traducido en una extraordinaria apertura hacia el exterior: las exportaciones globales de Calabria han superado la barrera simbólica de los mil millones de euros, impulsadas por la alimentación y las bebidas, que representan casi el 40% de las ventas transfronterizas.",
  "I prodotti simbolo": "Los productos simbólicos",
  "I prodotti simbolo della regione — dalle clementine IGP al bergamotto, dai vini autoctoni all’olio extravergine d’oliva — hanno conquistato nuovi spazi nei mercati europei ed extra-UE, affrontando con resilienza anche le fisiologiche fasi di assestamento dei mercati globali nel 2026.": "Los productos emblemáticos de la región, desde las clementinas IGP hasta la bergamota, desde los vinos autóctonos hasta el aceite de oliva virgen extra, han conquistado nuevos espacios en los mercados europeos y extracomunitarios, afrontando también con resiliencia las fases fisiológicas de ajuste de los mercados globales en 2026.",
  "Indice di crescita dell'export agroalimentare": "Índice de crecimiento de las exportaciones agroalimentarias",
  "livelli pre-pandemia": "niveles prepandémicos",
  "Dai livelli pre-pandemia ai mercati europei ed extra-UE.": "Desde niveles prepandemia hasta mercados europeos y extracomunitarios.",
  "del valore dell'export": "del valor de exportación",
  "Quota del food & beverage sulle vendite oltreconfine.": "Participación de alimentos y bebidas en las ventas transfronterizas.",
  "I riconoscimenti": "los premios",
  "La regia della Regione Calabria": "La dirección de la Región de Calabria",
  "Risorse, giovani e primato green": "Recursos, jóvenes y primacía verde",
  "Dietro questo successo non c’è il caso, ma una precisa strategia politica e amministrativa guidata dalla Regione Calabria e dall’Assessorato all’Agricoltura. Negli ultimi quattro anni l’ente regionale ha cambiato passo, trasformando la gestione dei fondi europei in liquidità immediata e opportunità concrete per chi lavora la terra. Attraverso l’agenzia pagatrice ARCEA, solo nell’ultimo anno sono stati liquidati oltre": "Detrás de este éxito no hay ninguna posibilidad, sino una estrategia política y administrativa precisa liderada por la Región de Calabria y el Departamento de Agricultura. En los últimos cuatro años el organismo regional ha cambiado de ritmo, transformando la gestión de los fondos europeos en liquidez inmediata y oportunidades concretas para quienes trabajan la tierra. A través del organismo pagador ARCEA, sólo en el último año se les ha pagado más",
  "61 milioni di euro, mentre l’attuazione del nuovo Complemento di Sviluppo Rurale (CSR 2023–2027) ha posto la Calabria ai vertici nazionali per velocità ed efficienza di spesa.": "61 millones de euros, mientras que la aplicación del nuevo Complemento de Desarrollo Rural (CSR 2023-2027) ha colocado a Calabria a la cabeza nacional en rapidez y eficiencia del gasto.",
  "Azienda Regionale per le Erogazioni in Agricoltura": "Empresa Regional de Desembolsos Agropecuarios",
  "L’agenzia pagatrice della Regione: nell’ultimo anno ha liquidato oltre": "El organismo pagador de la Región: en el último año ha pagado más",
