  "Comuni — infrastrutture rurali, strade interpoderali, reti idriche": "Municipios: infraestructuras rurales, caminos entre explotaciones agrícolas, redes de agua",
  "Bando SRE01 — insediamento giovani agricoltori under 41": "Anuncio SRE01 - Asentamiento de jóvenes agricultores menores de 41 años",
