  "della SAU è biologico": "de la UAA es orgánica",
  "La Calabria è la prima regione in Italia per incidenza di superfici coltivate con metodo biologico.": "Calabria es la primera región de Italia en cuanto a incidencia de superficies cultivadas ecológicamente.",
  "Oltre il": "Más allá del",
  "% della Superficie Agricola Utilizzata: un primato che certifica una vocazione naturale alla sostenibilità.": "% de Superficie Agrícola Utilizada: un récord que certifica una vocación natural por la sostenibilidad.",
  "Il futuro nelle mani dei giovani": "El futuro en manos de los jóvenes",
  "La cura dei territori": "Cuidado de los territorios",
  "La leadership nel biologico": "Liderazgo en orgánico",
  "Con oltre 44 milioni di euro attraverso il bando SRE01, la Regione ha finanziato il 100% delle domande ammesse per l’insediamento di nuovi agricoltori under 41, scommettendo sul ricambio generazionale e sull’innovazione tecnologica.": "Con más de 44 millones de euros a través de la convocatoria SRE01, la Región ha financiado el 100% de las solicitudes admitidas para el establecimiento de nuevos agricultores menores de 41 años, apostando por el relevo generacional y la innovación tecnológica.",
  "Oltre 61 milioni di euro destinati ai Comuni calabresi per ammodernare le infrastrutture rurali, migliorare le strade interpoderali e potenziare le reti idriche nelle aree interne.": "Más de 61 millones de euros asignados a los municipios de Calabria para modernizar las infraestructuras rurales, mejorar los caminos entre explotaciones y reforzar las redes de agua en las zonas interiores.",
  "Oggi la Calabria è la prima regione in Italia per incidenza di superfici coltivate con metodo biologico, superando il 36% della Superficie Agricola Utilizzata.": "Hoy Calabria es la primera región de Italia por la incidencia de superficies cultivadas ecológicamente, superando el 36% de la superficie agrícola utilizada.",
  "ARSAC e “Calabria Straordinaria”": "ARSAC y la “Calabria extraordinaria”",
  "Il braccio operativo dell’eccellenza": "El brazo operativo de excelencia",
  "Per trasformare un prodotto eccellente in un brand vincente serve un ponte tra la ricerca scientifica, l’assistenza in campo e i grandi palcoscenici internazionali. È questo il ruolo svolto dall’ARSAC, il braccio tecnico-operativo della Regione che, consolidata la propria governance, ha accompagnato passo dopo passo la crescita delle imprese.": "Para transformar un producto excelente en una marca ganadora, se necesita un puente entre la investigación científica, la asistencia sobre el terreno y los grandes escenarios internacionales. Este es el papel desempeñado por ARSAC, el brazo técnico-operativo de la Región que, consolidada su gobernanza, ha acompañado paso a paso el crecimiento de las empresas.",
  "Azienda Regionale per lo Sviluppo dell’Agricoltura Calabrese": "Empresa Regional para el Desarrollo de la Agricultura de Calabria",
  "Ricerca, sperimentazione e divulgazione in campo: centri dimostrativi, bollettini agrometeorologici e tutela della biodiversità calabrese.": "Investigación, experimentación y difusión sobre el terreno: centros de demostración, boletines agrometeorológicos y protección de la biodiversidad de Calabria.",
  "Innovazione nei campi": "Innovación en los campos",
  "La rete dei Centri Sperimentali Dimostrativi e il lavoro quotidiano dei divulgatori agricoli portano l’innovazione direttamente nei campi.": "La red de Centros Experimentales de Demostración y el trabajo diario de los comunicadores agrícolas llevan la innovación directamente a los campos.",
  "Bollettini agrometeorologici e fitosanitari settimanali, fondamentali per ridurre l’impatto ambientale e ottimizzare i costi.": "Boletines agrometeorológicos y fitosanitarios semanales, fundamentales para reducir el impacto ambiental y optimizar costes.",
  "Tutela della biodiversità e delle razze autoctone come il Suino Nero di Calabria, la bovina Podolica e il Fico Dottato.": "Protección de la biodiversidad y de las razas autóctonas como el Cerdo Negro de Calabria, el ganado Podolica y el Fico Dottato.",
  "Così l’ente garantisce che la tradizione cammini al fianco della scienza.": "De esta forma la organización garantiza que la tradición camina junto a la ciencia.",
  "Presenze alle fiere 2026": "Asistencia a las ferias de 2026",
  "TuttoFood — Milano (aziende)": "TuttoFood — Milán (empresas)",
  "Vinitaly — Verona (cantine)": "Vinitaly — Verona (bodegas)",
  "Oltre 133 aziende protagoniste.": "Más de 133 empresas líderes.",
  "Più di 100 cantine.": "Más de 100 bodegas.",
  "Niente più presenze frammentate, ma un’unica grande casa comune nelle più prestigiose vetrine mondiali, con una presenza di primo piano anche a Macfrut e al Merano Wine Festival: un lavoro capillare che permette anche ai piccoli produttori di dialogare direttamente con i grandi buyer internazionali.": "No más presencias fragmentadas, sino una única gran casa común en los escaparates mundiales más prestigiosos, con presencia destacada también en Macfrut y en el Merano Wine Festival: un trabajo generalizado que permite también a los pequeños productores dialogar directamente con los grandes compradores internacionales.",
  "Uno sguardo al futuro": "Una mirada al futuro",
  "Consolidare i risultati": "Consolidar los resultados",
  "La sfida dei prossimi anni sarà consolidare questi risultati, affrontando nodi storici come i costi energetici, l’aggregazione delle filiere e il potenziamento della logistica integrata attorno all’hub di Gioia Tauro. Ma la strada è tracciata: la Calabria agroalimentare ha dimostrato di avere le risorse, le competenze istituzionali e il talento imprenditoriale per essere non più una semplice scommessa, ma una straordinaria certezza del Made in Italy.": "El desafío de los próximos años será consolidar estos resultados, abordando cuestiones históricas como los costos de la energía, la agregación de las cadenas de suministro y el fortalecimiento de la logística integrada en torno al hub de Gioia Tauro. Pero el camino está claro: la Calabria agroalimentaria ha demostrado que tiene los recursos, las capacidades institucionales y el talento empresarial para dejar de ser una simple apuesta, sino una extraordinaria certeza del Made in Italy.",
  "Cifre e affermazioni come riportate nel documento di riferimento. Foto: Salvatore Rigracciolo (pubblico dominio), Nenad Stojkovic (CC BY 2.0), Leslie Seaton (CC BY 2.0), Salvatore Migliari (CC BY 3.0), filandariweb.com (CC BY-SA 3.0) — Wikimedia Commons.": "Cifras y declaraciones según lo informado en el documento de referencia. Fotos: Salvatore Rigracciolo (dominio público), Nenad Stojkovic (CC BY 2.0), Leslie Seaton (CC BY 2.0), Salvatore Migliari (CC BY 3.0), filandariweb.com (CC BY-SA 3.0) — Wikimedia Commons.",
