  ": il soggetto che utilizza Radici Calabria per pubblicare e offrire prodotti, servizi o altre prestazioni.": ": la persona que utiliza Radici Calabria para publicar y ofrecer productos, servicios u otros servicios.",
  ": il soggetto terzo che fornisce l'infrastruttura tecnica per il metodo di pagamento selezionato.": ": el tercero que proporciona la infraestructura técnica para el método de pago seleccionado.",
  ": il soggetto terzo che fornisce l'infrastruttura tecnica per il pagamento selezionato.": ": el tercero que proporciona la infraestructura técnica para el pago seleccionado.",
  ": la persona che utilizza la piattaforma e può acquistare dal venditore.": ": la persona que utiliza la plataforma y puede comprarle al vendedor.",
  ": la piattaforma e l'infrastruttura tecnologica gestita da [DENOMINAZIONE DEL GESTORE].": ": la plataforma e infraestructura tecnológica gestionada por [NOMBRE DEL RESPONSABLE].",
  ": la piattaforma e l'infrastruttura tecnologica gestita da [Inserisci Nome Azienda/Ditta].": ": la plataforma e infraestructura tecnológica administrada por [Insertar nombre de la empresa].",
  ": la proposta relativa a un prodotto, servizio o prestazione pubblicata dal Venditore.": ": la propuesta relativa a un producto, servicio o prestación publicada por el Vendedor.",
  ": la richiesta del Cliente relativa a un'offerta, secondo il flusso applicabile.": ": la solicitud de oferta del Cliente, según el flujo aplicable.",
  ": la richiesta di acquisto o prenotazione riferita a un'offerta del venditore, secondo il flusso applicabile.": ": la solicitud de compra o reserva referida a una oferta del vendedor, según el flujo aplicable.",
  ": lo spazio o profilo del Venditore pubblicato sulla piattaforma.": ": el espacio o perfil del Vendedor publicado en la plataforma.",
  "Il Gestore non acquista, non rivende e non commercializza in proprio i prodotti o i servizi offerti dai Venditori.": "El Gestor no compra, revende ni comercializa por sí solo los productos o servicios ofrecidos por los Vendedores.",
  "Il trattamento dei dati personali avviene secondo l'Informativa Privacy di Radici Calabria e la normativa applicabile, incluso il Regolamento (UE) 2016/679 (GDPR). Ciascun utente professionale opera quale autonomo titolare del trattamento per i dati trattati nell'ambito delle proprie attività, nei limiti e secondo le rispettive responsabilità previste dalla normativa applicabile.": "El procesamiento de datos personales se realiza de acuerdo con la Política de Privacidad de Radici Calabria y la legislación aplicable, incluido el Reglamento (UE) 2016/679 (GDPR). Cada usuario profesional actúa como responsable independiente del tratamiento de los datos tratados en el marco de sus actividades, dentro de los límites y según las respectivas responsabilidades establecidas por la legislación aplicable.",
  "La Piattaforma integra e utilizza servizi, contenuti e strumenti informativi forniti da soggetti terzi, inclusi i componenti e i widget informativi resi disponibili all'interno della Piattaforma. I dati, le informazioni, gli aggiornamenti e i risultati visualizzati attraverso tali componenti sono forniti e gestiti dai rispettivi soggetti o servizi di origine. La responsabilità dell'esattezza, completezza, aggiornamento, disponibilità e continuità di tali dati e informazioni è a carico del relativo soggetto o servizio di origine, secondo le proprie condizioni e responsabilità. Radici Calabria non modifica né garantisce autonomamente tali dati e non assume responsabilità per eventuali inesattezze, ritardi, omissioni, indisponibilità o interruzioni imputabili al servizio o al soggetto che li fornisce, fatti salvi gli obblighi inderogabili previsti dalla legge.": "La Plataforma integra y utiliza servicios, contenidos y herramientas de información proporcionados por terceros, incluidos los componentes y widgets de información disponibles dentro de la Plataforma. Los datos, la información, las actualizaciones y los resultados mostrados a través de dichos componentes son proporcionados y mantenidos por sus respectivas entidades o servicios de origen. La responsabilidad de la exactitud, integridad, actualización, disponibilidad y continuidad de dichos datos e información recae en la entidad o servicio que los origina, de acuerdo con sus propias condiciones y responsabilidades. Radici Calabria no modifica ni garantiza de forma independiente dichos datos y no asume responsabilidad por posibles inexactitudes, retrasos, omisiones, indisponibilidad o interrupciones imputables al servicio o a quien lo presta, sin perjuicio de las obligaciones obligatorias establecidas por la ley.",
  "aggiornare offerte, prezzi e disponibilità;": "actualizar ofertas, precios y disponibilidad;",
  "collaborare alle verifiche tecniche e documentali;": "colaborar en los controles técnicos y documentales;",
  "gestire gli ordini e le comunicazioni in modo tempestivo;": "gestionar pedidos y comunicaciones en tiempo y forma;",
  "utilizzare l'account e il negozio per finalità lecite e autorizzate;": "utilizar su cuenta y tienda para fines legales y autorizados;",
  "mantenere corretti i dati identificativi e commerciali;": "mantener correctos los datos identificativos y comerciales;",
  "proteggere le credenziali e segnalare accessi sospetti;": "proteger las credenciales e informar accesos sospechosos;",
