  "Riconoscimenti": "Agradecimientos",
  "DOP, IGP e STG sono denominazioni europee; PAT è un riconoscimento regionale; DE.CO. è una denominazione comunale.": "DOP, IGP y ETG son denominaciones europeas; PAT es un reconocimiento regional; DE.CO. es un nombre municipal.",
  "Torna a tutti i territori": "Regresar a todos los territorios",
