  "Bottega DEMO che raccoglie le Eccellenze del territorio di Castrovillari e del Pollino. Ambiente dimostrativo, non un'attività reale aderente a LocalHub.": "Tienda DEMO que reúne las excelencias de la zona de Castrovillari y Pollino. Entorno de demostración, no un negocio real de LocalHub.",
  "Negozio DEMO dedicato ai dolci e ai sapori tradizionali di Castrovillari. Ambiente dimostrativo, non un'attività reale aderente a LocalHub.": "Tienda DEMO dedicada a los postres y sabores tradicionales de Castrovillari. Entorno de demostración, no un negocio real de LocalHub.",
  "Vetrina DEMO dei sapori del Parco Nazionale del Pollino: miele, olio e vino del territorio. Ambiente dimostrativo, non un'attività reale aderente a LocalHub.": "Muestra DEMO de los sabores del Parque Nacional del Pollino: miel, aceite y vino locales. Entorno de demostración, no un negocio real de LocalHub.",
  "Enoteca DEMO dedicata ai vini dell'area del Pollino: le sottozone di Terre di Cosenza e il Moscato al governo di Saracena. Ambiente dimostrativo, non un'attività reale aderente a LocalHub.": "Tienda de vinos DEMO dedicada a los vinos de la zona del Pollino: las subzonas de Terre di Cosenza y el Moscato bajo el gobierno de Saracena. Entorno de demostración, no un negocio real de LocalHub.",
