  "Formaggio estivo di latte di capra e pecora, da tavola o da grattugia. Al kg.": "Queso de verano elaborado con leche de cabra y oveja, para mesa o para rallar. Por kg.",
  "Ortaggio DOP dell'area di Rotonda, polpa compatta e sapore dolce. Venduta al kg.": "Verdura DOP de la zona de la Rotonda, pulpa compacta y sabor dulce. Vendido por kg.",
  "Formaggio DOP a pasta filata, stagionato: da gratinare o alla piastra. Al kg.": "Queso cuajado DOP curado, curado: para gratinar o asar. Por kg.",
  "Biscotti da forno a base di farina, nella selezione demo di Mani in Pasta.": "Galletas horneadas a base de harina, en la selección de demostración Mani in Pasta.",
  "Taralli da forno, prodotto a base di farina nella selezione demo di Mani in Pasta.": "Taralli al horno, producto a base de harina en la selección de demostración Mani in Pasta.",
  "Olive schiacciate in stile calabrese, prodotto dimostrativo nella selezione delle eccellenze.": "Aceitunas trituradas al estilo calabrés, producto de demostración en la selección de excelencia.",
