  "Specialità calabrese spalmabile e piccante, con peperoncino. Formato indicativo circa 350 g.": "Especialidad calabresa untable y especiada, con guindilla. Tamaño aproximado 350 g aproximadamente.",
  "Pasta tradizionale calabrese nel formato fileja, confezione da 500 g.": "Pasta tradicional de Calabria en formato fileja, paquete de 500 g.",
