  "Torrone mielato della tradizione dolciaria di Bagnara Calabra, confezione da 500 g.": "Turrón meloso de la tradición repostera de Bagnara Calabra, envase de 500 g.",
  "Pecorino del Monte Poro DOP, stagionato in forme tradizionali. Al kg.": "Pecorino del Monte Poro DOP, madurado en formas tradicionales. Por kg.",
